func (o *Character) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "ActiveBuffs":
		rels, ok := retrieved.(ActiveBuffSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.ActiveBuffs = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
			}
		}
		return nil
	case "HPEvents":
		rels, ok := retrieved.(HPEventSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.HPEvents = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
			}
		}
		return nil
	case "RoundStates":
		rels, ok := retrieved.(RoundStateSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.RoundStates = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
			}
		}
		return nil
	case "SpellSlots":
		rels, ok := retrieved.(SpellSlotSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.SpellSlots = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
			}
		}
		return nil
	case "XPEvents":
		rels, ok := retrieved.(XPEventSlice)
		if !ok {
			return fmt.Errorf("character cannot load %T as %q", retrieved, name)
		}

		o.R.XPEvents = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.Character = o
			}
		}
		return nil
	default:
		return fmt.Errorf("character has no relationship %q", name)
	}
}

