// LoadActiveBuffs loads the character's ActiveBuffs into the .R struct
func (o *Character) LoadActiveBuffs(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.ActiveBuffs = nil

	related, err := o.ActiveBuffs(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Character = o
	}

	o.R.ActiveBuffs = related
	return nil
}

// LoadActiveBuffs loads the character's ActiveBuffs into the .R struct
func (os CharacterSlice) LoadActiveBuffs(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	activeBuffs, err := os.ActiveBuffs(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.ActiveBuffs = nil
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range activeBuffs {

			if !(o.ID == rel.CharacterID) {
				continue
			}

			rel.R.Character = o

			o.R.ActiveBuffs = append(o.R.ActiveBuffs, rel)
		}
	}

	return nil
}

