func (os CharacterSlice) LoadRoundStates(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	roundStates, err := os.RoundStates(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.RoundStates = nil
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range roundStates {

			if !(o.ID == rel.CharacterID) {
				continue
			}

			rel.R.Character = o

			o.R.RoundStates = append(o.R.RoundStates, rel)
		}
	}

	return nil
}

