type characterCountThenLoader[Q orm.Loadable] struct {
	ActiveBuffs func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	HPEvents    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	RoundStates func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	SpellSlots  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	XPEvents    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildCharacterCountThenLoader[Q orm.Loadable]() characterCountThenLoader[Q] {
	type ActiveBuffsCountInterface interface {
		LoadCountActiveBuffs(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type HPEventsCountInterface interface {
		LoadCountHPEvents(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundStatesCountInterface interface {
		LoadCountRoundStates(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type SpellSlotsCountInterface interface {
		LoadCountSpellSlots(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type XPEventsCountInterface interface {
		LoadCountXPEvents(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return characterCountThenLoader[Q]{
		ActiveBuffs: countThenLoadBuilder[Q](
			"ActiveBuffs",
			func(ctx context.Context, exec bob.Executor, retrieved ActiveBuffsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountActiveBuffs(ctx, exec, mods...)
			},
		),
		HPEvents: countThenLoadBuilder[Q](
			"HPEvents",
			func(ctx context.Context, exec bob.Executor, retrieved HPEventsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountHPEvents(ctx, exec, mods...)
			},
		),
		RoundStates: countThenLoadBuilder[Q](
			"RoundStates",
			func(ctx context.Context, exec bob.Executor, retrieved RoundStatesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountRoundStates(ctx, exec, mods...)
			},
		),
		SpellSlots: countThenLoadBuilder[Q](
			"SpellSlots",
			func(ctx context.Context, exec bob.Executor, retrieved SpellSlotsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountSpellSlots(ctx, exec, mods...)
			},
		),
		XPEvents: countThenLoadBuilder[Q](
			"XPEvents",
			func(ctx context.Context, exec bob.Executor, retrieved XPEventsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountXPEvents(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountActiveBuffs loads the count of ActiveBuffs into the C struct
func (o *Character) LoadCountActiveBuffs(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.ActiveBuffs(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.ActiveBuffs = &count
	return nil
}

// LoadCountActiveBuffs loads the count of ActiveBuffs for a slice in a single batch query
func (os CharacterSlice) LoadCountActiveBuffs(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int64
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			ActiveBuffs.Columns.CharacterID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(ActiveBuffs.NameAs()),

		// WHERE fk IN (parent PKs)
		sm.Where(ActiveBuffs.Columns.CharacterID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(ActiveBuffs.Columns.CharacterID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int64]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.ActiveBuffs = &count
	}

	return nil
}

